diff --git a/app/parent/children/[studentId]/ChildRecordActions.tsx b/app/parent/children/[studentId]/ChildRecordActions.tsx
new file mode 100644
index 0000000..713c7f2
--- /dev/null
+++ b/app/parent/children/[studentId]/ChildRecordActions.tsx
@@ -0,0 +1,177 @@
+"use client";
+
+// Parent per-child export + delete affordances (Phase 7 R5). CLIENT component —
+// NO lib/grade import here (the grade is computed server-side and never shipped).
+// The delete uses a focus-managed confirm modal with an "export first" warning and
+// a NON-COLOR destructive affordance (an explicit typed confirmation), not a red
+// button alone.
+
+import { useEffect, useRef, useState } from "react";
+import { Button } from "../../../../components/ui/Button";
+import {
+  deleteChildRecord,
+  exportChildRecord,
+  type ExportResult,
+} from "./actions";
+
+export interface ChildRecordActionsProps {
+  studentId: string;
+  childName: string;
+}
+
+export function ChildRecordActions({ studentId, childName }: ChildRecordActionsProps) {
+  const [exporting, setExporting] = useState(false);
+  const [exportError, setExportError] = useState<string | null>(null);
+  const [modalOpen, setModalOpen] = useState(false);
+
+  async function onExport() {
+    setExporting(true);
+    setExportError(null);
+    const res: ExportResult = await exportChildRecord(studentId);
+    setExporting(false);
+    if (!res.ok || !res.artifact) {
+      setExportError(res.error ?? "Export failed.");
+      return;
+    }
+    downloadJson(res.artifact, `a3-record-${childName}.json`);
+  }
+
+  return (
+    <div className="flex flex-wrap items-center gap-3">
+      <Button variant="secondary" onClick={onExport} loading={exporting}>
+        Export record
+      </Button>
+      <Button variant="quiet" onClick={() => setModalOpen(true)}>
+        Delete record
+      </Button>
+      {exportError && (
+        <p role="alert" className="text-[12.5px] text-[var(--color-error)]">
+          {exportError}
+        </p>
+      )}
+      {modalOpen && (
+        <DeleteConfirmModal
+          studentId={studentId}
+          childName={childName}
+          onClose={() => setModalOpen(false)}
+        />
+      )}
+    </div>
+  );
+}
+
+function DeleteConfirmModal({
+  studentId,
+  childName,
+  onClose,
+}: {
+  studentId: string;
+  childName: string;
+  onClose: () => void;
+}) {
+  const [confirmText, setConfirmText] = useState("");
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [done, setDone] = useState(false);
+  const inputRef = useRef<HTMLInputElement>(null);
+
+  // Focus management: focus the confirm input on open; restore focus on close.
+  useEffect(() => {
+    const prev = document.activeElement as HTMLElement | null;
+    inputRef.current?.focus();
+    function onKey(e: KeyboardEvent) {
+      if (e.key === "Escape" && !busy) onClose();
+    }
+    document.addEventListener("keydown", onKey);
+    return () => {
+      document.removeEventListener("keydown", onKey);
+      prev?.focus?.();
+    };
+  }, [busy, onClose]);
+
+  // NON-COLOR destructive affordance: require typing DELETE to enable the action.
+  const armed = confirmText.trim().toUpperCase() === "DELETE";
+
+  async function onConfirm() {
+    if (!armed) return;
+    setBusy(true);
+    setError(null);
+    const res = await deleteChildRecord(studentId);
+    setBusy(false);
+    if (!res.ok) {
+      setError(res.error ?? "Delete failed.");
+      return;
+    }
+    setDone(true);
+  }
+
+  return (
+    <div
+      className="fixed inset-0 z-50 grid place-items-center bg-[rgba(15,23,42,0.35)] px-6"
+      role="dialog"
+      aria-modal="true"
+      aria-labelledby="delete-record-title"
+    >
+      <div className="w-full max-w-[460px] rounded-[16px] border border-border bg-surface p-7 shadow-lg">
+        <h2 id="delete-record-title" className="font-display text-[18px] font-semibold text-ink">
+          Delete {childName}&rsquo;s record
+        </h2>
+
+        {done ? (
+          <>
+            <p className="mt-3 text-[14px] leading-[1.55] text-ink-500">
+              The record has been deleted. Operational data was anonymized; the
+              evidence ledger is preserved for audit.
+            </p>
+            <div className="mt-6 flex justify-end">
+              <Button variant="primary" onClick={onClose}>
+                Done
+              </Button>
+            </div>
+          </>
+        ) : (
+          <>
+            <p className="mt-3 text-[14px] leading-[1.55] text-ink-500">
+              Export this record first — deleting it may limit future NCAA or
+              transcript support. This anonymizes {childName}&rsquo;s work; it cannot
+              be undone.
+            </p>
+            <label className="mt-5 block text-[13px] font-medium text-ink-700">
+              Type DELETE to confirm
+              <input
+                ref={inputRef}
+                value={confirmText}
+                onChange={(e) => setConfirmText(e.target.value)}
+                className="mt-1.5 w-full rounded-[10px] border border-border-strong bg-canvas px-3 py-2 text-[14px] text-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
+                aria-label="Type DELETE to confirm"
+              />
+            </label>
+            {error && (
+              <p role="alert" className="mt-3 text-[12.5px] text-[var(--color-error)]">
+                {error}
+              </p>
+            )}
+            <div className="mt-6 flex justify-end gap-3">
+              <Button variant="quiet" onClick={onClose} disabled={busy}>
+                Cancel
+              </Button>
+              <Button variant="primary" onClick={onConfirm} disabled={!armed} loading={busy}>
+                Delete record
+              </Button>
+            </div>
+          </>
+        )}
+      </div>
+    </div>
+  );
+}
+
+function downloadJson(data: unknown, filename: string) {
+  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
+  const url = URL.createObjectURL(blob);
+  const a = document.createElement("a");
+  a.href = url;
+  a.download = filename;
+  a.click();
+  URL.revokeObjectURL(url);
+}
diff --git a/app/parent/children/[studentId]/actions.ts b/app/parent/children/[studentId]/actions.ts
new file mode 100644
index 0000000..369696d
--- /dev/null
+++ b/app/parent/children/[studentId]/actions.ts
@@ -0,0 +1,106 @@
+"use server";
+
+// Parent per-child export + delete server actions (Phase 7 R5). SUPABASE-mode
+// only; memory mode short-circuits. NO lib/grade import in a client module — this
+// is a server action, so computing the grade here is allowed.
+//
+// R5 ORDERING (enforced in the action, not just the UI):
+//   delete = (a) verify parent-of authz, (b) generate the export FIRST,
+//            (c) only THEN erase operational data (anonymize-in-place).
+// Audit row carries NO PII: { actorId, actorRole, studentId, recordType }.
+
+import { getAuthMode } from "../../../../lib/auth/mode";
+import { getCurrentParent, parentOwnsChild } from "../../../../lib/auth/parent";
+import { getRepository } from "../../../../lib/repository/server";
+import { computeGrade } from "../../../../lib/grade";
+import { buildNcaaExport, type NcaaExport } from "../../../../lib/ncaa-export";
+
+export interface ExportResult {
+  ok: boolean;
+  error?: string;
+  /** The generated artifact (returned for download in supabase mode). */
+  artifact?: NcaaExport & { watermark: string };
+}
+
+export interface DeleteResult {
+  ok: boolean;
+  error?: string;
+}
+
+const MEMORY_NOTICE = "This action is not available in this environment.";
+const GENERIC_FAIL = "We couldn't complete that just now. Please try again.";
+
+/**
+ * Build the export artifact for a child the verified parent owns (R5b). PURE of
+ * side effects beyond the repository reads + the watermark stamp.
+ */
+async function buildArtifact(studentId: string, nowIso: string): Promise<NcaaExport & { watermark: string }> {
+  const repo = await getRepository();
+  const [profile, graph, states, updates] = await Promise.all([
+    repo.getStudent(studentId),
+    repo.getGraph(),
+    repo.getSkillStates(studentId),
+    repo.listMasteryUpdates(studentId),
+  ]);
+  if (!profile) throw new Error("student not found");
+  // Grade computed SERVER-SIDE (R6). Summative intake deferred → not credit-eligible.
+  const grade = computeGrade(states, graph, updates, { nowIso });
+  const ncaa = buildNcaaExport(profile, graph, states, updates, grade, nowIso);
+  return {
+    ...ncaa,
+    watermark: `A3 Academy support package · ${profile.displayName} · generated ${nowIso}`,
+  };
+}
+
+/** Self-service export (R5). Verifies parent-of, then builds the artifact. */
+export async function exportChildRecord(studentId: string): Promise<ExportResult> {
+  if (getAuthMode() !== "supabase") return { ok: false, error: MEMORY_NOTICE };
+  const parent = await getCurrentParent();
+  if (!parent) return { ok: false, error: "Please sign in again to continue." };
+  if (!(await parentOwnsChild(parent.uid, studentId))) return { ok: false, error: GENERIC_FAIL };
+
+  try {
+    const nowIso = new Date().toISOString();
+    const artifact = await buildArtifact(studentId, nowIso);
+    return { ok: true, artifact };
+  } catch {
+    return { ok: false, error: GENERIC_FAIL };
+  }
+}
+
+/**
+ * Self-service delete (R5). ORDER: authz → generate export FIRST → erase. The
+ * audit row carries NO PII body. The export artifact is returned so the parent
+ * becomes custodian of the record (§3 export-first-then-delete).
+ */
+export async function deleteChildRecord(studentId: string): Promise<DeleteResult> {
+  if (getAuthMode() !== "supabase") return { ok: false, error: MEMORY_NOTICE };
+  const parent = await getCurrentParent();
+  if (!parent) return { ok: false, error: "Please sign in again to continue." };
+  // (a) verify authz BEFORE any erase.
+  if (!(await parentOwnsChild(parent.uid, studentId))) return { ok: false, error: GENERIC_FAIL };
+
+  try {
+    const nowIso = new Date().toISOString();
+    const repo = await getRepository();
+    // (b) generate the export FIRST (§3 export-then-delete) — if it throws, we
+    // never reach the erase, so no data is destroyed without a record produced.
+    await buildArtifact(studentId, nowIso);
+    // (c) only THEN erase operational data (anonymize-in-place; append-only kept).
+    await repo.eraseOperationalData(studentId);
+    // Audit row — NO PII body (R5): { actorId, actorRole, studentId, recordType }.
+    try {
+      await repo.appendAccessLog({
+        actorId: parent.uid,
+        actorRole: "parent", // administrator of record (§7)
+        studentId,
+        recordType: "operational_erase",
+      });
+    } catch {
+      /* audit best-effort; the erase already succeeded */
+    }
+    return { ok: true };
+  } catch {
+    return { ok: false, error: GENERIC_FAIL };
+  }
+}
diff --git a/app/parent/children/[studentId]/page.tsx b/app/parent/children/[studentId]/page.tsx
new file mode 100644
index 0000000..78cba71
--- /dev/null
+++ b/app/parent/children/[studentId]/page.tsx
@@ -0,0 +1,261 @@
+// /parent/children/[studentId] — the per-child parent dashboard (Phase 7 §12-13,
+// R3/R6/R8/R9/R11). SERVER component, ParentShell, parent-scoped. The grade is
+// computed SERVER-SIDE (NO lib/grade import in any client child) and only plain
+// data is passed down.
+//
+// MEMORY MODE: this surface is supabase-only (mirrors /parent). In memory mode it
+// renders a calm "not available" rather than throwing.
+//
+// Renders: course-progress ring (0-100%), projected grade (letter suppressed/grey
+// while no summative, R3 disclaimer visible), 5-10 subject masteries (StatusPill
+// bands), proof modules, stuck nodes, export + delete (server actions).
+
+import { notFound, redirect } from "next/navigation";
+import { getAuthMode } from "../../../../lib/auth/mode";
+import { getCurrentParent, parentOwnsChild } from "../../../../lib/auth/parent";
+import { getRepository } from "../../../../lib/repository/server";
+import { computeMasteryAll } from "../../../../lib/mastery-engine";
+import { recommend } from "../../../../lib/adaptive-router";
+import { computeFlags } from "../../../../lib/insight/flags";
+import { computeGrade } from "../../../../lib/grade";
+import { rollUpSubjects } from "../../../../lib/grade/subjects";
+import { buildProofModules, buildStuckNodes } from "../../../../lib/insight/proof";
+import { creditTier } from "../../../../lib/transcript";
+import { ParentShell } from "../../../../components/layout/ParentShell";
+import { PageHeader } from "../../../../components/ui/PageHeader";
+import { Card } from "../../../../components/ui/Card";
+import { InsetPanel, LabeledSection } from "../../../../components/ui/Panels";
+import { ProgressRing } from "../../../../components/gamification/ProgressRing";
+import { ProofModule } from "../../../../components/insight/ProofModule";
+import { ChildRecordActions } from "./ChildRecordActions";
+
+const SUBJECT_BAND_LABEL: Record<string, string> = {
+  not_started: "Not started",
+  developing: "Getting started",
+  progressing: "Progressing",
+  strong: "Strong",
+};
+
+export const metadata = {
+  title: "Student record — A3 Academy Family",
+};
+
+export default async function ParentChildDashboard({
+  params,
+}: {
+  params: Promise<{ studentId: string }>;
+}) {
+  if (getAuthMode() !== "supabase") return <NotAvailable />;
+
+  const { studentId } = await params;
+  const parent = await getCurrentParent();
+  if (!parent) redirect("/auth/sign-in");
+
+  // Authz: the verified parent must own this child (R5).
+  if (!(await parentOwnsChild(parent.uid, studentId))) notFound();
+
+  const repo = await getRepository();
+  const profile = await repo.getStudent(studentId);
+  if (!profile) notFound();
+
+  const [graph, states, attempts, updates] = await Promise.all([
+    repo.getGraph(),
+    repo.getSkillStates(studentId),
+    repo.listAttempts(studentId),
+    repo.listMasteryUpdates(studentId),
+  ]);
+
+  const nowIso = new Date().toISOString();
+  const batch = computeMasteryAll(studentId, states, graph, nowIso);
+  void recommend(batch.results, states, graph); // parity with other surfaces
+
+  // SERVER-SIDE grade (R6). Summative intake deferred → not credit-eligible.
+  const grade = computeGrade(states, graph, updates, { nowIso });
+  const lockedIds = new Set(grade.locked);
+
+  const subjects = rollUpSubjects(graph, states, batch.results, lockedIds);
+
+  const creditNodeIds = graph.nodes
+    .filter((n) => creditTier(n) === "algebra1-credit")
+    .map((n) => n.id);
+  const proofModules = buildProofModules(
+    graph,
+    states,
+    batch.results,
+    updates,
+    lockedIds,
+    creditNodeIds,
+  ).slice(0, 8);
+
+  const flags = computeFlags(graph, attempts, updates, states, batch.results, null, nowIso);
+  const stuckNodes = buildStuckNodes(graph, batch.results, flags).slice(0, 6);
+
+  // Course-progress 0-100% = mastered credit-bearing nodes / credit-bearing scope.
+  const creditTotal = creditNodeIds.length;
+  const masteredCredit = creditNodeIds.filter((id) => states[id]?.status === "mastered").length;
+  const courseProgress = creditTotal === 0 ? 0 : masteredCredit / creditTotal;
+
+  return (
+    <ParentShell parentName={parent.name}>
+      <div className="fade-in">
+        <PageHeader
+          eyebrow={`Family · ${profile.displayName}`}
+          title={`${profile.displayName}'s progress`}
+          subhead="Course progress, projected grade, and the evidence behind each placement. Read-only."
+        />
+
+        {/* Top: progress ring + projected grade. */}
+        <div className="grid grid-cols-1 gap-5 lg:grid-cols-2">
+          <Card>
+            <LabeledSection label="Course progress">
+              <div className="flex items-center gap-6">
+                <ProgressRing
+                  value={courseProgress}
+                  ariaLabel={`Course progress: ${masteredCredit} of ${creditTotal} skills`}
+                  label={`${Math.round(courseProgress * 100)}%`}
+                  sublabel={`${masteredCredit} of ${creditTotal} skills`}
+                />
+                <p className="text-[13px] leading-[1.55] text-ink-500">
+                  Share of the credit-bearing Algebra 1 skills {profile.displayName} has
+                  mastered so far.
+                </p>
+              </div>
+            </LabeledSection>
+          </Card>
+
+          <Card>
+            <LabeledSection label="Projected grade">
+              <ProjectedGrade
+                pct={grade.pct}
+                letter={grade.letter}
+                summativePresent={grade.summativePresent}
+                disclaimer={grade.disclaimer}
+              />
+            </LabeledSection>
+          </Card>
+        </div>
+
+        {/* Subject masteries. */}
+        <LabeledSection label="Subject areas" className="mt-5">
+          <Card>
+            <ul className="grid gap-2.5">
+              {subjects.map((s) => (
+                <li
+                  key={s.id}
+                  className="flex items-center justify-between gap-3 border-b border-selected pb-2.5 last:border-0 last:pb-0"
+                >
+                  <span className="truncate text-[13px] font-medium text-ink">{s.label}</span>
+                  <span className="flex shrink-0 items-center gap-3">
+                    <span className="font-mono text-[11px] text-ink-500">
+                      {s.masteredLocked}/{s.total}
+                    </span>
+                    <span className="text-[12.5px] font-medium text-ink-700">
+                      {SUBJECT_BAND_LABEL[s.band]}
+                    </span>
+                  </span>
+                </li>
+              ))}
+            </ul>
+          </Card>
+        </LabeledSection>
+
+        {/* Proof modules + stuck nodes. */}
+        <div className="mt-5 grid grid-cols-1 gap-5 lg:grid-cols-2">
