+    id,
+    title: `Skill ${id}`,
+    domain: "d",
+    tier: 0,
+    prereqs: [],
+    standards: { ccss, state: null },
+    objective: `Objective for ${id}`,
+    misconceptionTags: [],
+    visual: null,
+    contextHooks: {
