+
+function state(over: Partial<StudentSkillState>): StudentSkillState {
+  return {
+    mastery: 0,
+    status: "unknown",
+    phase: 1 as Phase,
+    attempts: 0,
+    correct: 0,
+    hints: 0,
+    timeMs: 0,
+    recent: [],
+    transfer: false,
+    lastAttemptAt: null,
+    masteredAt: null,
